-- Wipe every role and access rule, then recreate both from bootstrap (bootstrap/genBootstrap.ts output,
-- the roles block and the access_rules blocks only - no policy row, no catalog data).
--
-- users.role and user_roles.role reference roles.name with ON DELETE RESTRICT, so a role a user holds cannot
-- be deleted. Instead of deferring that check (D1 validates the whole database at commit, so any unrelated
-- orphan row fails it), roles nobody holds are deleted and the bootstrap roles are upserted: a held role keeps
-- its row and takes the bootstrap label, protected and provisioned values. No foreign key is touched.
--
-- Run this first. Every role it returns is held by a user but not recreated below, so it would survive the
-- wipe with no rules:
--   SELECT role FROM users UNION SELECT role FROM user_roles
--   EXCEPT SELECT column1 FROM (VALUES ('everyone'),('employee'),('team_lead'),('manager'),('hr_admin'),('payroll_admin'),('super_admin'));
--
-- DELETE FROM access_rules also removes per-user rules, per-document shares and ticket shares, which
-- bootstrap does not recreate.
DELETE FROM access_rules;
DELETE FROM roles
WHERE name NOT IN (SELECT role FROM users)
  AND name NOT IN (SELECT role FROM user_roles);
-- roles_one_provisioned allows one provisioned role; clear it so the upsert below can set employee's.
UPDATE roles SET provisioned = 0;

ON CONFLICT(name) DO UPDATE SET
  label = excluded.label,
  protected = excluded.protected,
  provisioned = excluded.provisioned,
  updated_at = CAST(strftime('%s','now') AS INTEGER) * 1000;
